def solve(nums):
    count_map = {0: -1}
    max_len = count = 0
    for i, x in enumerate(nums):
        count += 1 if x == 1 else -1
        if count in count_map:
            max_len = max(max_len, i - count_map[count])
        else:
            count_map[count] = i
    return max_len

